#include "ActualAuthoringRecording.h"
int main(int argc,char **argv){const QString report=argument(1);argc=1;TWApp app(argc,argv);QTimer::singleShot(0,&app,[&]{
 QJsonArray checks;int failures=0;auto check=[&](QString n,bool b){checks.append(QJsonObject{{"name",n},{"passed",b}});if(!b)++failures;};
 if(!qEnvironmentVariable("TEXLINE_TEST_DESKTOP").startsWith("TeXlineValidation-")){app.exit(1);return;}
 const QString folder=QFileInfo(report).absolutePath(),root=folder+"/main.tex";
 const QString source="\\documentclass{article}\n\\usepackage{graphicx,booktabs}\n\\begin{document}\n\\section{Results}\nWe compare the observed measurements.\n\\begin{figure}[htbp]\n\\centering\n\\includegraphics[width=0.65\\linewidth]{sample.png}\n\\caption{Observed response}\\label{fig:response}\n\\end{figure}\n\\begin{table}[htbp]\n\\centering\n\\begin{tabular}{lr}\n\\toprule\nGroup & Response \\\\\n\\midrule\nControl & 1.2 \\\\\nTreatment & 2.4 \\\\\n\\bottomrule\n\\end{tabular}\n\\caption{Group summary}\\label{tab:groups}\n\\end{table}\n\\bibliography{references}\n\\end{document}\n";
 put(root,source.toUtf8());put(folder+"/references.bib",QByteArray("@article{smith2025, title={Measurements under uncertainty}, author={Smith, Alex and Lee, Jordan}, year={2025}, journal={Research Methods}}\n@article{chen2024, title={A reproducible comparison}, author={Chen, Lin}, year={2024}}\n"));
 QImage picture(800,460,QImage::Format_RGB32);picture.fill(Qt::white);{QPainter p(&picture);p.setRenderHint(QPainter::Antialiasing);p.setPen(QPen(QColor("#747e87"),2));p.drawLine(80,380,750,380);p.drawLine(80,380,80,35);p.setPen(QPen(QColor("#59768c"),4));QPainterPath curve;curve.moveTo(80,355);curve.cubicTo(270,350,350,180,740,75);p.drawPath(curve);p.setPen(QColor("#4c565e"));p.setFont(QFont("Segoe UI",18));p.drawText(280,430,"Observed response");}picture.save(folder+"/sample.png");
 Tw::Settings().setValue("openPDFwithTeX",false);auto *w=new TeXDocumentWindow(root);w->resize(1280,800);w->show();settle(600);auto select=[&](QString token){auto c=w->textCursor();c.setPosition(w->textDoc()->editorText().indexOf(token)+3);w->editor()->setTextCursor(c);};
 select("\\includegraphics");Research::editResearchObject(w);QPointer<QDialog> dialog=w->findChild<QDialog*>("researchObjectDialog");check("figure dialog opens",dialog);if(dialog){waitFor([&]{return dialog->findChild<QLabel*>("researchObjectPreview")->property("researchDraftReady").toBool();},45000);Recording r;r.start(folder+"/figure-flow",w);r.action("Figure: actual preview on the left and properties on the right");settle(800);auto *caption=dialog->findChild<QPlainTextEdit*>("researchObjectCaption");r.click(caption);key(caption,Qt::Key_A,Qt::ControlModifier);type(caption,"Observed response across conditions");settle(600);auto *tabs=dialog->findChild<QTabWidget*>("researchObjectTabs");r.action("Full LaTeX remains directly editable");r.click(dialog->findChild<QToolButton*>("researchObjectSourceTab"));settle(650);r.click(dialog->findChild<QToolButton*>("researchObjectLayoutTab"));settle(650);auto *buttons=dialog->findChild<QDialogButtonBox*>("researchObjectButtons");r.action("Apply edits in one undo step");r.click(buttons->button(QDialogButtonBox::Apply));r.finish();check("figure recording inputs complete",!r.failures);}
 select("\\begin{tabular}");Research::editResearchObject(w);dialog=w->findChild<QDialog*>("researchObjectDialog");check("table dialog opens",dialog);if(dialog){waitFor([&]{return dialog->findChild<QLabel*>("researchObjectPreview")->property("researchDraftReady").toBool();},45000);Recording r;r.start(folder+"/table-flow",w);r.action("Table cells and typeset preview stay side by side");auto *grid=dialog->findChild<QTableWidget*>("researchTableGrid");r.clickAt(grid->viewport(),grid->visualItemRect(grid->item(2,1)).center());grid->editItem(grid->item(2,1));settle(100);auto *cell=grid->findChild<QLineEdit*>();if(cell){key(cell,Qt::Key_A,Qt::ControlModifier);type(cell,"2.8");key(cell,Qt::Key_Return);}check("edited table produces its current preview before Apply",waitFor([&]{return dialog->findChild<QPlainTextEdit*>("researchObjectSource")->toPlainText().contains("2.8")&&dialog->findChild<QLabel*>("researchObjectPreview")->property("researchDraftReady").toBool();},15000));r.action("The typeset preview now shows the changed value");settle(1100);auto *buttons=dialog->findChild<QDialogButtonBox*>("researchObjectButtons");r.action("Apply the changed cell without replacing the whole document");r.click(buttons->button(QDialogButtonBox::Apply));r.finish();check("table recording inputs complete",!r.failures);}
 auto c=w->textCursor();c.setPosition(w->textDoc()->editorText().indexOf("We compare"));w->editor()->setTextCursor(c);w->findChild<QAction*>("researchInsertCitation")->trigger();dialog=w->findChild<QDialog*>("researchCitationDialog");check("citation dialog opens",dialog);if(dialog){auto *results=dialog->findChild<QListWidget*>("researchCitationList");waitFor([&]{return results&&results->count()>0;});Recording r;r.start(folder+"/citation-flow",w);r.action("Local search shows results and structured metadata side by side");auto *query=dialog->findChild<QLineEdit*>("researchCitationSearch");r.click(query);type(query,"Smith");settle(700);r.action("Page locator updates the exact insertion source");auto *locator=dialog->findChild<QLineEdit*>("researchCitationLocator");r.click(locator);type(locator,"12--14");settle(900);auto *buttons=dialog->findChild<QDialogButtonBox*>("researchCitationButtons");r.click(buttons?buttons->button(QDialogButtonBox::Ok):nullptr);r.finish();check("citation recording inputs complete",!r.failures);if(dialog&&dialog->isVisible())dialog->reject();}
 w->setModified(false);put(report,QJsonDocument(QJsonObject{{"checks",checks},{"failures",failures},{"actualWindowCapture",true},{"physicalInputVerified",false}}).toJson());app.exit(failures?1:0);
 });return app.exec();}
